const enemyTypes={basic:{hp:72,speed:1.55,damage:9,range:1.55,guard:.12,color:0x39464b},fast:{hp:56,speed:2.05,damage:7,range:1.45,guard:.08,color:0x70392f},heavy:{hp:142,speed:1.05,damage:15,range:1.8,guard:.2,color:0x33383a},defensive:{hp:88,speed:1.32,damage:8,range:1.5,guard:.42,color:0x68543c},boss:{hp:340,speed:1.48,damage:18,range:1.85,guard:.23,color:0x702e26}};
function spawnEnemy(type='basic',angle=null){
 const stats=enemyTypes[type]||enemyTypes.basic,ang=angle==null?rand(-2.2,2.2):angle,dist=type==='boss'?4.4:rand(4.2,6.1),root=new THREE.Group(),rig=makeRig(type);root.add(rig);scene.add(root);root.position.set(Math.sin(ang)*dist,0,-Math.cos(ang)*dist);root.rotation.y=Math.atan2(-root.position.x,root.position.z);
 const factor=1+Math.max(0,round-1)*.14;const e={root,rig,type,hp:stats.hp*factor,maxHp:stats.hp*factor,speed:stats.speed*(1+Math.max(0,round-1)*.045),damage:stats.damage*factor,range:stats.range,guard:stats.guard,attack:0,attackCooldown:rand(.8,2),think:rand(.4,1.2),state:'approach',stun:0,hitFlash:0,walk:rand(0,7),attackPhase:0,side:Math.random()<.5?-1:1,dead:false,score:0};enemies.push(e);return e;
}
function startMode(m){mode=m;round=1;wave=1;score=0;streak=0;comboTimer=0;gameTime=0;playerMaxHealth=100+Math.floor(save.level/3)*8;playerHealth=playerMaxHealth;playerMaxStamina=100+Math.min(30,save.upgrades*5);stamina=playerMaxStamina;attackLock=0;finisherReady=false;enemies.forEach(e=>scene.remove(e.root));enemies=[];effects.forEach(o=>scene.remove(o));effects=[];decals.forEach(o=>scene.remove(o));decals=[];running=true;paused=false;ui.menu.classList.add('hidden');ui.pause.classList.add('hidden');ui.result.classList.add('hidden');ui.hud.style.display='block';$('#damageflash').classList.remove('active');$('#combo').classList.remove('show');$('#hint').textContent='';
 const count=m==='training'?1:m==='boss'?1:m==='story'?2:3;
 if(m==='boss')spawnEnemy('boss',0);else for(let i=0;i<count;i++)spawnEnemy(m==='training'?'basic':i===1&&m==='story'?'fast':i===2&&m==='survival'?'heavy':'basic',i*Math.PI*2/count);
 if(m==='training')$('#hint').textContent='TRAINING · YOUR STRIKES DO NOT HURT YOU';updateHud();if(!audioCtx){try{audioCtx=new (window.AudioContext||window.webkitAudioContext)()}catch(e){}}
}
function updateHud(){const hp=clamp(playerHealth/playerMaxHealth*100,0,100),st=clamp(stamina/playerMaxStamina*100,0,100);$('#hpBar').style.width=hp+'%';$('#stBar').style.width=st+'%';$('#hpText').textContent=Math.ceil(playerHealth);$('#stText').textContent=Math.ceil(stamina);$('#foes').textContent=String(enemies.filter(e=>!e.dead).length).padStart(2,'0');$('#foesText').textContent=mode==='survival'?'WAVE '+String(wave).padStart(2,'0'):'OPPONENTS';$('#stage').textContent=mode==='story'?'THE YARD · ROUND '+round:mode==='boss'?'CHAMPION · THE LAST BOUT':mode==='training'?'TRAINING · FREE PRACTICE':'SURVIVAL · WAVE '+wave;
}
function playTone(freq,dur,type='triangle',vol=.12,slide=0){if(!audioCtx||soundVol<=0)return;try{const osc=audioCtx.createOscillator(),gain=audioCtx.createGain();osc.type=type;osc.frequency.setValueAtTime(freq,audioCtx.currentTime);if(slide)osc.frequency.exponentialRampToValueAtTime(Math.max(30,freq*slide),audioCtx.currentTime+dur);gain.gain.setValueAtTime(vol*soundVol,audioCtx.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+dur);osc.connect(gain);gain.connect(audioCtx.destination);osc.start();osc.stop(audioCtx.currentTime+dur)}catch(e){}}
function soundHit(power=1,blocked=false){if(blocked){playTone(180,.13,'square',.08,.7);playTone(420,.09,'triangle',.04,.5)}else{playTone(power>1.3?75:115,.16,'triangle',.2,.35);playTone(power>1.3?540:330,.1,'sawtooth',.045,.4)}}
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('show'),900)}
function createBurst(pos,power=1,blocked=false){
 const colors=blocked?[0xffd796,0xffffff,0x8293a0]:[0xad3027,0xe24b39,0xf4b27a];const n=blocked?7:Math.round(9+power*7);
 for(let i=0;i<n;i++){const m=new THREE.MeshBasicMaterial({color:colors[i%colors.length],transparent:true,opacity:.9});const p=new THREE.Mesh(new THREE.SphereGeometry(rand(.018,.055),6,5),m);p.position.copy(pos);scene.add(p);p.userData={v:new THREE.Vector3(rand(-1,1)*power,rand(.3,1.5)*power,rand(-1,1)*power),life:rand(.22,.56),max:.56};effects.push(p)}
 if(!blocked&&power>1.25){const d=new THREE.Mesh(new THREE.CircleGeometry(rand(.12,.25),12),new THREE.MeshBasicMaterial({color:0x78231f,transparent:true,opacity:.55,depthWrite:false}));d.rotation.x=-Math.PI/2;d.position.set(pos.x,.012,pos.z);scene.add(d);decals.push(d);if(decals.length>18){scene.remove(decals.shift())}}
}
function nearestTarget(maxDist=2.35){let best=null,bd=maxDist;const dir=new THREE.Vector3(-Math.sin(yaw),0,-Math.cos(yaw));for(const e of enemies){if(e.dead)continue;const delta=e.root.position.clone().sub(player.root.position);const d=delta.length();const facing=delta.normalize().dot(dir);if(d<bd&&facing>-.1){best=e;bd=d}}return best}
const attackDefs={jab:{name:'JAB',damage:11,stamina:8,reach:2.0,duration:.34,hand:0,power:.8,kind:'hand',color:0},cross:{name:'CROSS',damage:15,stamina:11,reach:2.15,duration:.43,hand:1,power:1,kind:'hand'},hook:{name:'HOOK',damage:19,stamina:15,reach:1.85,duration:.54,hand:0,power:1.25,kind:'hand'},elbow:{name:'ELBOW',damage:22,stamina:19,reach:1.65,duration:.56,hand:1,power:1.35,kind:'hand'},uppercut:{name:'UPPERCUT',damage:26,stamina:23,reach:1.8,duration:.66,hand:0,power:1.6,kind:'upper'},frontkick:{name:'FRONT KICK',damage:17,stamina:16,reach:2.4,duration:.58,hand:1,power:1.15,kind:'kick'},roundhouse:{name:'ROUNDHOUSE',damage:24,stamina:24,reach:2.2,duration:.72,hand:0,power:1.45,kind:'kick'},heavykick:{name:'HEAVY KICK',damage:33,stamina:30,reach:2.35,duration:.88,hand:1,power:1.8,kind:'kick'}};
let moveIndex=0,activeMove=null,moveElapsed=0,attackHitDone=false;
function doAttack(kind='light'){
 if(!running||paused||attackLock>0||dodgeTime>0)return;if(stamina<8){toast('OUT OF STAMINA');return}
 let key;if(kind==='light'){const chain=['jab','cross','hook','elbow'];key=chain[moveIndex%chain.length];moveIndex++}else if(kind==='heavy')key='uppercut';else if(kind==='kick')key=moveIndex%2?'roundhouse':'frontkick';else if(kind==='heavykick')key='heavykick';else return;
 const def={...attackDefs[key]},style=styles[save.style]||styles.Boxer;def.damage*=style.damage;def.duration/=style.speed;def.stamina/=style.stamina;
 if(stamina<def.stamina){toast('OUT OF STAMINA');return}stamina-=def.stamina;activeMove=def;moveElapsed=0;attackHitDone=false;attackLock=def.duration*.72;playTone(key.includes('kick')?145:190,.12,'triangle',.035,.75);
