import { createRequire } from 'node:module';
const require=createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const {chromium}=require('playwright');
const browser=await chromium.launch({headless:true,args:['--no-sandbox','--disable-dev-shm-usage','--disable-gpu']});
const context=await browser.newContext({viewport:{width:1280,height:800}});
const page=await context.newPage();
const errors=[];page.on('pageerror',e=>errors.push(e.message));page.on('console',m=>{if(m.type()==='error')errors.push(m.text())});
await page.goto('http://localhost:3002',{waitUntil:'domcontentloaded'});await page.locator('#startGame').click();
const snapshot=()=>page.evaluate(()=>({hp:document.querySelector('#hpText').textContent,foes:document.querySelector('#foes').textContent,stage:document.querySelector('#stage').textContent,mobile:getComputedStyle(document.querySelector('.mobile-controls')).display,resultHidden:document.querySelector('#result').classList.contains('hidden'),resultVisibility:getComputedStyle(document.querySelector('#result')).visibility}));
await page.waitForTimeout(500);const initial=await snapshot();
await page.keyboard.down('KeyW');await page.waitForTimeout(700);await page.keyboard.up('KeyW');
for(let i=0;i<16;i++){await page.keyboard.press('KeyJ');await page.waitForTimeout(240)}
await page.waitForTimeout(1200);const after=await snapshot();
await page.screenshot({path:'/tmp/opencode/iron-veil-validation.jpeg',type:'jpeg',quality:85,timeout:15000});
await page.locator('#pauseBtn').click();const pauseVisible=await page.locator('#pause').evaluate(e=>!e.classList.contains('hidden'));const hiddenResultVisibility=await page.locator('#result').evaluate(e=>getComputedStyle(e).visibility);await page.locator('#resume').click();const resumeHidden=await page.locator('#pause').evaluate(e=>e.classList.contains('hidden'));
await page.waitForTimeout(300);const resumed=await snapshot();
await page.setViewportSize({width:390,height:844});await page.waitForTimeout(500);const mobile=await page.evaluate(()=>({controls:getComputedStyle(document.querySelector('.mobile-controls')).display,stick:document.querySelector('#stick').getBoundingClientRect().toJSON(),buttons:document.querySelector('.touchbuttons').getBoundingClientRect().toJSON(),pause:document.querySelector('#pauseBtn').getBoundingClientRect().toJSON()}));
await page.screenshot({path:'/tmp/opencode/iron-veil-mobile.jpeg',type:'jpeg',quality:85,timeout:15000});
console.log(JSON.stringify({initial,after,pauseVisible,hiddenResultVisibility,resumeHidden,resumed,mobile,errors},null,2));await browser.close();

