import { createRequire } from 'node:module';
const require=createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const {chromium}=require('playwright');
const browser=await chromium.launch({headless:true,args:['--no-sandbox','--disable-dev-shm-usage','--disable-gpu']});
const context=await browser.newContext({viewport:{width:640,height:400}});
const page=await context.newPage();
const errors=[];page.on('pageerror',e=>errors.push(e.message));page.on('console',m=>{if(m.type()==='error')errors.push(m.text())});
await page.goto('http://localhost:3002',{waitUntil:'domcontentloaded'});
await page.locator('#openSettings').click();await page.locator('#quality').selectOption('Low');await page.locator('#closeSettings').click();await page.locator('#startGame').click();
const snap=()=>page.evaluate(()=>({hp:document.querySelector('#hpText').textContent,stamina:document.querySelector('#stText').textContent,foes:document.querySelector('#foes').textContent,stage:document.querySelector('#stage').textContent,resultHidden:document.querySelector('#result').classList.contains('hidden')}));
await page.waitForTimeout(500); const initial=await snap();
await page.keyboard.down('KeyW');await page.waitForTimeout(1000);await page.keyboard.up('KeyW');await page.waitForTimeout(500);const close=await snap();
for(let i=0;i<16;i++){await page.keyboard.press(i%2?'KeyJ':'KeyK');await page.waitForTimeout(480)}
await page.waitForTimeout(1000);const combat=await snap();
await page.locator('#pauseBtn').click({timeout:3000});const pauseVisible=await page.locator('#pause').evaluate(e=>!e.classList.contains('hidden'));await page.locator('#resume').click();const resumeHidden=await page.locator('#pause').evaluate(e=>e.classList.contains('hidden'));
await page.setViewportSize({width:390,height:844});await page.waitForTimeout(300);const mobile=await page.evaluate(()=>{let a=document.querySelector('#touchLook').getBoundingClientRect(),b=document.querySelector('#pauseBtn').getBoundingClientRect(),s=document.querySelector('#stick').getBoundingClientRect(),buttons=document.querySelector('.touchbuttons').getBoundingClientRect();return {controls:getComputedStyle(document.querySelector('.mobile-controls')).display,touchLook:a.toJSON(),pause:b.toJSON(),stick:s.toJSON(),buttons:buttons.toJSON(),overlap:!(a.right<=b.left||a.left>=b.right||a.bottom<=b.top||a.top>=b.bottom)}});
await page.screenshot({path:'/tmp/opencode/iron-veil-mobile.jpeg',type:'jpeg',quality:85,timeout:15000});
console.log(JSON.stringify({initial,close,combat,pauseVisible,resumeHidden,mobile,errors},null,2));await browser.close();
