import { createRequire } from 'node:module';
const require=createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const {chromium}=require('playwright');
const browser=await chromium.launch({headless:true,args:['--no-sandbox','--disable-dev-shm-usage','--disable-gpu']});
const context=await browser.newContext({viewport:{width:640,height:400}});
const page=await context.newPage();
const errors=[];page.on('pageerror',e=>errors.push(e.message));page.on('console',m=>{if(m.type()==='error')errors.push(m.text())});
await page.addInitScript(()=>{HTMLElement.prototype.requestPointerLock=function(){};document.exitPointerLock=()=>{}});
await page.route('http://localhost:3002/**',async route=>{
 const response=await route.fetch();let body=await response.text();
 body=body.replace('init3d();bind();updateMeta();animate();','window.__ironDebug={state:()=>({running,paused,round,mode,player:{x:player.root.position.x,z:player.root.position.z,yaw},enemies:enemies.map(e=>({type:e.type,hp:Math.round(e.hp),dead:e.dead,x:+e.root.position.x.toFixed(2),z:+e.root.position.z.toFixed(2),state:e.state})),health:Math.ceil(playerHealth),stamina:Math.ceil(stamina),foes:enemies.filter(e=>!e.dead).length}),align:()=>{const live=enemies.filter(e=>!e.dead);live.forEach((e,i)=>{e.think=999;e.attack=0;e.state=\'approach\';e.root.position.set(i===0?0:5,0,i===0?-1.45:0)});yaw=0;}};init3d();bind();updateMeta();animate();');
 await route.fulfill({...response,body});
});
await page.goto('http://localhost:3002',{waitUntil:'domcontentloaded'});
await page.locator('#openSettings').click();await page.locator('#quality').selectOption('Low');await page.locator('#closeSettings').click();await page.locator('#startGame').click();await page.waitForTimeout(300);
const initial=await page.evaluate(()=>window.__ironDebug.state());
await page.evaluate(()=>window.__ironDebug.align());
const before=await page.evaluate(()=>window.__ironDebug.state());
for(let i=0;i<8;i++){
 await page.keyboard.press('KeyK');
 await page.waitForTimeout(750);
 await page.evaluate(()=>window.__ironDebug.align());
 const s=await page.evaluate(()=>window.__ironDebug.state());
 console.log('combat',i+1,JSON.stringify({round:s.round,foes:s.foes,hp:s.enemies.map(e=>e.hp),stamina:s.stamina}));
 if(s.round>1||s.foes===0)break;
}
await page.waitForTimeout(800);
const after=await page.evaluate(()=>window.__ironDebug.state());
const hud={hp:await page.locator('#hpText').textContent(),foes:await page.locator('#foes').textContent(),stage:await page.locator('#stage').textContent()};
// Verify a genuine browser pointer interaction against the visible pause control.
const pauseBox=await page.locator('#pauseBtn').boundingBox();
const hitTarget=await page.evaluate(({x,y})=>{const el=document.elementFromPoint(x,y);return {id:el?.id,tag:el?.tagName}}, {x:pauseBox.x+pauseBox.width/2,y:pauseBox.y+pauseBox.height/2});
await page.mouse.click(pauseBox.x+pauseBox.width/2,pauseBox.y+pauseBox.height/2);
await page.waitForTimeout(100);
const pauseVisible=await page.locator('#pause').evaluate(e=>!e.classList.contains('hidden'));
let resumeHidden=null;if(pauseVisible){const box=await page.locator('#resume').boundingBox();await page.mouse.click(box.x+box.width/2,box.y+box.height/2);await page.waitForTimeout(100);resumeHidden=await page.locator('#pause').evaluate(e=>e.classList.contains('hidden'))}
console.log(JSON.stringify({initial,before,after,hud,hitTarget,pauseVisible,resumeHidden,errors},null,2));
await page.screenshot({path:'/tmp/opencode/iron-veil-focused-combat.jpeg',type:'jpeg',quality:85,timeout:15000});
await browser.close();

